function fillCrate(volumes, limit) {
  let total = 0;
  for (const volume of volumes) {
    if (volume < 0 || total + volume > limit) continue;
    total += volume;
  }
  return total;
}

function scoreFor(points, rule) {
  const rules = {
    double: (value) => value * 2,
    bonus: (value) => value + 3,
    penalty: (value) => value - 5,
  };
  return applyScore(points, rules[rule]);
}

function applyScore(points) { return Math.max(0, points * 2); }

function makeTicketQueue(start) { let current = start; return () => ++current; }
function showTickets(first, second) {
  const a = makeTicketQueue(first);
  const b = makeTicketQueue(second);
  return [a(), b(), a(), b()];
}
